mapper.select:
SELECT * FROM ( SELECT m.material_id AS materialId, t.tenant_code AS tenantCode, m.material_code AS materialCode, m.material_name AS materialName, m.item_type AS itemType, m.material_spec AS materialSpec, m.material_weight AS materialWeight, m.unit AS unit, m.etc AS etc, ROW_NUMBER() OVER (ORDER BY m.material_code) AS rn FROM tb_material_info m JOIN tb_tenant t ON t.tenant_id = m.tenant_id WHERE m.delete_status = 'N'
AND t.tenant_code = #{tenantCode}
AND ( LOWER(m.material_name) LIKE '%' || LOWER(#{keyword}) || '%' OR LOWER(COALESCE(m.material_spec, '')) LIKE '%' || LOWER(#{keyword}) || '%' OR LOWER(COALESCE(m.item_type, '')) LIKE '%' || LOWER(#{keyword}) || '%' OR m.material_code LIKE '%' || #{keyword} || '%' )
) material_query WHERE rn BETWEEN #{firstIndex} AND #{lastIndex} ORDER BY rn

SELECT COUNT(1) FROM tb_material_info m JOIN tb_tenant t ON t.tenant_id = m.tenant_id WHERE m.delete_status = 'N'
AND t.tenant_code = #{tenantCode}
AND ( LOWER(m.material_name) LIKE '%' || LOWER(#{keyword}) || '%' OR LOWER(COALESCE(m.material_spec, '')) LIKE '%' || LOWER(#{keyword}) || '%' OR LOWER(COALESCE(m.item_type, '')) LIKE '%' || LOWER(#{keyword}) || '%' OR m.material_code LIKE '%' || #{keyword} || '%' )

SELECT u.user_id
FROM tb_user u
JOIN tb_login_account la ON la.login_id = u.login_id
WHERE la.tenant_id = #{tenantId}
  AND la.login_code = #{loginCode}
LIMIT 1

SELECT MAX(material_code)
FROM tb_material_info
WHERE tenant_id = #{value}
